import React, { useState } from "react";

import "./Board.css";

const Board = () => {
    const [board, setBoard] = useState(Array(9).fill(null));

    const handleClick = (i) => {
        const copyBoard = [...board];
        copyBoard[i] = "X";
        setBoard(copyBoard);
    }

    return (
        <div className='board'>
            {board.map((square) => (
                <div key={square} className='square' onClick={handleClick}>
                    {square}
                </div>
            ))}
        </div>
    );
};

export default Board;
